//! The stance HUD as sprites and flat bands: which parts are drawn, where, and with which palette.
//!
//! The art lives in `assets/hud/sprites/stance_hud_art.rs`, generated by `showcase-vector/hudart`.
//! Every repeated part (a health cell, a gem) is one sprite drawn at a fixed step, and a colour
//! state (lit, empty, the other stance) is a different palette over the same texels, so two parts in
//! different states are the same pixels by construction. Axis-aligned areas are flat rectangles, so
//! nothing here depends on how the GPU fills a slanted triangle.
//!
//! A bar comes in a few sizes, each pixel art of its own and never scaled at run time (scaling would
//! break the identical cells). The bar in front is full size; the bar behind is a smaller size, as if
//! further back, and the sizes between are used for the frames while the bars trade places.
//!
//! The composition is written once against a `draw` callback, like `stance_hud_layout.rs`: the guest
//! turns each [`Op`] into a packet, the host viewer (`hudart`'s `hudview`) paints them into a frame.
//! This file has no dependencies, so both include it by path.

/// A rectangle of the atlas, in texels.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SpriteRect {
    pub u: u8,
    pub v: u8,
    pub w: u8,
    pub h: u8,
}

/// Rows `y0..y1` of a bar plate in one flat colour. A `glass` band is drawn semi-transparently
/// (average of the scene and the colour), so the scene shows through the well the cells sit in.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Band {
    pub y0: u8,
    pub y1: u8,
    pub rgb: [u8; 3],
    pub glass: bool,
}

/// One size of the bar. Columns are relative to the HUD column of the bar's origin (the left end
/// of every bar starts at `LCAP_X`), rows to the bar's first row.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SizeGeo {
    /// Distance between cells.
    pub pitch: i32,
    /// Left edge of the first cell's bottom row, and the row its top is on.
    pub cell_x0: i32,
    pub cell_row: i32,
    /// Rows of the bar.
    pub bar_h: i32,
    /// Left edge of the flat part of the plate and the first column of the right end.
    pub bar_x0: i32,
    pub cap_x: i32,
    /// Bands of the bar.
    pub band_count: usize,
    pub cell: SpriteRect,
    pub cap: SpriteRect,
    pub lcap: SpriteRect,
}

include!("../assets/hud/sprites/stance_hud_art.rs");

/// The two stances. Each has its own bar, which is a complete object: it can be drawn at any
/// position, in front or behind the other one, at any of its sizes.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Stance {
    Horizon,
    Zenith,
}

impl Stance {
    /// Position in the per-stance arrays of [`HudState`] and in the generated tables.
    pub const fn index(self) -> usize {
        match self {
            Self::Horizon => 0,
            Self::Zenith => 1,
        }
    }

    /// The other stance.
    pub const fn other(self) -> Self {
        match self {
            Self::Horizon => Self::Zenith,
            Self::Zenith => Self::Horizon,
        }
    }
}

/// Ticks (of 60 a second) the two bars take to trade places: half a second. The swap is drawn from
/// the tick it has reached, so every frame the game renders shows the bars somewhere new, at any
/// frame rate.
pub const SWAP_TICKS: u16 = 30;

/// Frames of the swap in the demos and grids (`demo`, the `HUD_SWAP` frame): frame `n` of them is
/// the swap `n / SWAP_FRAMES` of the way.
pub const SWAP_FRAMES: u8 = 8;

/// How far the bars bow out sideways while they trade places, at the middle of the swap.
pub const SWAP_BOW: i32 = 22;

/// How far the bar going back rises above its way, and the bar coming forward dips below it, at the
/// middle of the swap: the bars go round each other rather than along a line.
pub const SWAP_ARC: i32 = 4;

/// How far the bars turn about the vertical axis at the middle of the swap, as the sine of the
/// angle in Q12 (about 21 degrees). The bar coming forward turns one way and the bar going back
/// the other, so they pass each other.
pub const SWAP_YAW_Q12: i32 = 2048;

/// Everything the HUD shows; packets built from it stay valid while it is equal.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct HudState {
    /// The active stance: the bar in front, or the one coming to the front during a swap.
    pub stance: Stance,
    /// Lit health cells of each stance's bar, 0 to [`COUNT`].
    pub health: [u8; 2],
    /// Lit ammunition gems, 0 to [`COUNT`]. One count for both stances: the gems do not change in
    /// a swap.
    pub energy: u8,
    /// 0 at rest. During a swap to `stance`, how far it has gone, 1 to 4095 of 4096.
    pub swap: u16,
    /// How far each stance's bar is unfolded, 0 (gone into the emblem) to [`REVEAL_MAX`] (fully
    /// out).
    pub reveal: [u8; 2],
    /// How far the gems are unfolded, in the same steps.
    pub ammo_reveal: u8,
    /// The emblem flashes: it is releasing the bars.
    pub pulse: bool,
    /// Keep the gems showing while the bars are folded.
    pub ammo_hint: bool,
    /// Pills breaking or loading, see [`AmmoFx`].
    pub fx: [PillFx; FX_SLOTS],
    /// Quadrants (0 to 3) of the pill after the last lit one that are already recharged.
    pub partial: u8,
    /// Pills `start..end` have been recharged but are waiting their turn to load: they still show
    /// empty.
    pub queued: (u8, u8),
}

impl HudState {
    /// The HUD at rest and fully unfolded.
    pub const fn rest(stance: Stance, health: [u8; 2], energy: u8) -> Self {
        Self {
            stance,
            health,
            energy,
            swap: 0,
            reveal: [REVEAL_MAX; 2],
            ammo_reveal: REVEAL_MAX,
            pulse: false,
            ammo_hint: false,
            fx: [PillFx::Idle; FX_SLOTS],
            partial: 0,
            queued: (0, 0),
        }
    }
}

/// Steps of the fold: a bar is fully out at this value and gone into the emblem at 0. At 30 frames
/// a second the front bar takes 8 frames (0.27 s) each way, the bar behind two more.
pub const REVEAL_MAX: u8 = 8;

/// Frames the bar behind trails the front bar by when the HUD folds or unfolds.
pub const FOLD_LAG: u8 = 2;

/// Frames the emblem flashes for when it releases the bars.
pub const PULSE_FRAMES: u8 = 2;

/// One thing to paint, in screen pixels.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Op {
    /// A flat rectangle, semi-transparent when `glass`.
    Rect {
        x: i32,
        y: i32,
        w: i32,
        h: i32,
        rgb: [u8; 3],
        glass: bool,
    },
    /// A sprite from the atlas, drawn 1:1 with CLUT number `clut` of [`CLUTS`]. With `glass` the
    /// palette entries that carry the semi-transparency bit blend with the scene.
    Sprite {
        x: i32,
        y: i32,
        src: SpriteRect,
        clut: usize,
        glass: bool,
    },
    /// The GPU's mask bit: with `set` every pixel drawn from now on is marked, with `check` pixels
    /// that are marked are not drawn over. Both off ends the special case.
    Mask { set: bool, check: bool },
    /// A flat quad with its corners anywhere (top-left, top-right, bottom-left, bottom-right), for
    /// the bars while they trade places.
    Quad {
        p: [(i16, i16); 4],
        rgb: [u8; 3],
        glass: bool,
    },
    /// A quad of the atlas: the texels of `src`, stretched over the corners (top-left, top-right,
    /// bottom-left, bottom-right) and drawn with CLUT number `clut`.
    TexQuad {
        p: [(i16, i16); 4],
        src: SpriteRect,
        clut: usize,
        glass: bool,
    },
}

/// Ops one HUD needs at most: every band of both bars, both ends of both bars, both bars' cells,
/// the emblem, the gems and four mask changes.
pub const MAX_OPS: usize = 2 * BAND_MAX + 9 + 3 * (COUNT as usize);

/// Where a bar is, relative to the HUD's origin, and which size it is.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Pose {
    pub x: i32,
    pub y: i32,
    pub size: usize,
}

/// Which emblem palette to draw.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EmblemLook {
    Of(Stance),
    Halfway,
    /// The flash of the emblem of this stance as it releases the bars.
    Pulse(Stance),
}

/// A bar on the move. The pieces of the bar are laid out in a plane with the geometry of a size
/// between two of the pixel art sizes, turned about the vertical axis and projected, so the bar
/// changes size, tilts and goes where it is going smoothly, to the pixel, whatever the frame rate.
/// (At rest the bar is not drawn this way: its sprites are cheaper for the GPU, and are the art.)
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Xf {
    /// Top-left corner of the bar (the first column of its left end, its first row), relative to the
    /// HUD's origin, in 1/256 pixels.
    pub x: i32,
    pub y: i32,
    /// How far back the bar is, in sizes of the art and 1/256 of one: 0 is the full size,
    /// `BACK_SIZE << 8` the bar behind.
    pub depth: i32,
    /// Sine and cosine of the turn about the vertical axis, Q12.
    pub sin: i32,
    pub cos: i32,
}

/// Where a bar is, and how it is drawn there.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Placement {
    /// At rest: pixel art of one size, drawn 1:1 from rectangles and sprites.
    Rest(Pose),
    /// On its way to the other place: the pieces of the bar are quads, placed every frame.
    Moving(Xf),
}

/// What a state looks like: the bars back to front and the emblem.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Scene {
    pub behind: (Stance, Placement),
    pub front: (Stance, Placement),
    pub emblem: EmblemLook,
}

/// Ease of a swap `p` of the way (Q12), 0 to 4096: it picks up speed and settles, as a smooth step.
fn ease(p: i32) -> i32 {
    let p2 = (p * p) >> 12;
    (3 * p2) - ((2 * p2 * p) >> 12)
}

/// `a` to `b` by `e / 4096`.
fn lerp(a: i32, b: i32, e: i32) -> i32 {
    a + (((b - a) * e) >> 12)
}

/// A bump that is 0 at both ends of the swap and 256 in the middle, from `e` (Q12).
fn bump(e: i32) -> i32 {
    let u = e >> 4;
    (4 * u * (256 - u)) >> 8
}

/// Top row of the bar behind.
const BACK_Y: i32 = FRONT_Y - LIFT + BACK_DROP;

/// A bar at rest at `pose` as the plane it moves in: the art's own size, not turned.
fn plane_of(pose: Pose) -> Xf {
    Xf {
        x: (LCAP_X + pose.x) << 8,
        y: pose.y << 8,
        depth: (pose.size as i32) << 8,
        sin: 0,
        cos: 4096,
    }
}

/// The bars' places and the draw order for `state`.
#[inline(never)]
pub fn scene(state: &HudState) -> Scene {
    let front_pose = Pose {
        x: 0,
        y: FRONT_Y,
        size: 0,
    };
    let back_pose = Pose {
        x: BACK_X,
        y: BACK_Y,
        size: BACK_SIZE,
    };
    let (incoming, outgoing) = (state.stance, state.stance.other());
    if state.swap == 0 || state.swap >= 4096 {
        return Scene {
            behind: (outgoing, Placement::Rest(back_pose)),
            front: (incoming, Placement::Rest(front_pose)),
            emblem: if state.pulse {
                EmblemLook::Pulse(incoming)
            } else {
                EmblemLook::Of(incoming)
            },
        };
    }
    // The bar coming forward goes down and grows, the one going back goes up and shrinks, bowing out
    // and turning the opposite ways so that they pass each other, and the one coming forward is drawn
    // in front from the middle on.
    let e = ease(i32::from(state.swap));
    let b = bump(e);
    let (back, front) = (plane_of(back_pose), plane_of(front_pose));
    let sin = (SWAP_YAW_Q12 * b) >> 8;
    let cos = 4096 - ((sin * sin) >> 13);
    let bow = SWAP_BOW * b;
    let arc = SWAP_ARC * b;
    let coming = Xf {
        x: lerp(back.x, front.x, e) - bow,
        y: lerp(back.y, front.y, e) + arc / 2,
        depth: lerp(back.depth, front.depth, e),
        sin,
        cos,
    };
    let going = Xf {
        x: lerp(front.x, back.x, e) + bow,
        y: lerp(front.y, back.y, e) - arc,
        depth: lerp(front.depth, back.depth, e),
        sin: -sin,
        cos,
    };
    let first_half = e < 2048;
    let (behind, front) = if first_half {
        ((incoming, coming), (outgoing, going))
    } else {
        ((outgoing, going), (incoming, coming))
    };
    Scene {
        behind: (behind.0, Placement::Moving(behind.1)),
        front: (front.0, Placement::Moving(front.1)),
        emblem: if e < 1600 {
            EmblemLook::Of(outgoing)
        } else if e < 2400 {
            EmblemLook::Halfway
        } else {
            EmblemLook::Of(incoming)
        },
    }
}

/// Frames a spent pill takes to break: a flash, cracks, then the four pieces spreading and fading.
pub const BREAK_FRAMES: u8 = 6;

/// Frames a pill takes to load: its four quadrants fill one a frame, then three frames of echo.
pub const LOAD_FRAMES: u8 = 7;

/// First frame of a load that is the echo, the pill being full.
const LOAD_ECHO: u8 = 4;

/// Frames between the pills of a recharge that gains several at once.
pub const LOAD_STAGGER: u8 = 2;

/// Pills that can show an effect at the same time. A pill that would need a sixth snaps to its
/// state with no effect.
pub const FX_SLOTS: usize = 5;

/// An effect on one pill, in the frame it is in.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PillFx {
    /// Nothing: the slot is free.
    Idle,
    /// The pill that was spent breaks, once `wait` more frames have passed (until then it still shows
    /// lit).
    Break { pill: u8, frame: u8, wait: u8 },
    /// The pill that was recharged loads and echoes, once `wait` more frames have passed (until then
    /// it still shows empty).
    Load { pill: u8, frame: u8, wait: u8 },
}

impl PillFx {
    /// The pill this effect is on.
    pub const fn pill(self) -> Option<u8> {
        match self {
            Self::Idle => None,
            Self::Break { pill, .. } | Self::Load { pill, .. } => Some(pill),
        }
    }
}

/// What an effect adds over a pill: whether the pill under it shows lit, and up to five more
/// sprites drawn over it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PillExtras {
    pub lit: bool,
    pub n: usize,
    pub ops: [Op; 5],
}

/// Which way each quadrant (in the order they fill) flies when the pill breaks.
const BREAK_DIRECTION: [(i32, i32); 4] = [(1, -1), (1, 1), (-1, 1), (-1, -1)];

/// How far the pieces are from the gem at each frame of the break from the third on.
const BREAK_SPREAD: [i32; 4] = [1, 2, 3, 4];

impl PillExtras {
    const NONE: Op = Op::Mask {
        set: false,
        check: false,
    };

    fn new(lit: bool) -> Self {
        Self {
            lit,
            n: 0,
            ops: [Self::NONE; 5],
        }
    }

    fn push(&mut self, op: Op) {
        self.ops[self.n] = op;
        self.n += 1;
    }
}

/// The pieces of pill `pill` as sprites: quadrant `i` of the gem moved `(dx, dy)` away.
fn quadrant(
    extras: &mut PillExtras,
    origin: (i32, i32),
    pill: i32,
    i: usize,
    away: (i32, i32),
    clut: usize,
    glass: bool,
) {
    let (qx, qy) = GEM_QUADRANT_AT[i];
    extras.push(Op::Sprite {
        x: origin.0 + GEM_X0 + GEM_PITCH * pill + qx + away.0,
        y: origin.1 + GEM_Y + qy + away.1,
        src: SPRITE_GEM_Q[i],
        clut,
        glass,
    });
}

/// What the effect `fx` of pill `pill` draws over the pill, with the HUD's top-left at `origin`.
pub fn pill_fx(origin: (i32, i32), pill: i32, fx: PillFx) -> PillExtras {
    let (gx, gy) = (origin.0 + GEM_X0 + GEM_PITCH * pill, origin.1 + GEM_Y);
    match fx {
        PillFx::Idle => PillExtras::new(false),
        PillFx::Break { wait, .. } if wait > 0 => PillExtras::new(true),
        PillFx::Load { wait, .. } if wait > 0 => PillExtras::new(false),
        PillFx::Break { frame, .. } => {
            let mut e = PillExtras::new(frame < 2);
            match frame {
                0 => e.push(Op::Sprite {
                    x: gx,
                    y: gy,
                    src: SPRITE_GEM,
                    clut: CLUT_GEM_FLASH,
                    glass: false,
                }),
                1 => e.push(Op::Sprite {
                    x: gx,
                    y: gy,
                    src: SPRITE_GEM_CRACK,
                    clut: CLUT_GEM_LIT,
                    glass: false,
                }),
                _ => {
                    let step = (frame - 2).min(3) as usize;
                    let spread = BREAK_SPREAD[step];
                    let (clut, glass) = match step {
                        0 => (CLUT_GEM_LIT, false),
                        1 => (CLUT_GEM_FADE_1, true),
                        _ => (CLUT_GEM_FADE_2, true),
                    };
                    for (i, dir) in BREAK_DIRECTION.iter().enumerate() {
                        quadrant(
                            &mut e,
                            origin,
                            pill,
                            i,
                            (dir.0 * spread, dir.1 * spread),
                            clut,
                            glass,
                        );
                    }
                }
            }
            e
        }
        PillFx::Load { frame, .. } => {
            let mut e = PillExtras::new(frame >= LOAD_ECHO);
            if frame < LOAD_ECHO {
                for i in 0..=frame as usize {
                    quadrant(&mut e, origin, pill, i, (0, 0), CLUT_GEM_LIT, false);
                }
            } else {
                let ring = (frame - LOAD_ECHO).min(2);
                let (grow, clut) = match ring {
                    0 => (1, CLUT_RING_BRIGHT),
                    1 => (2, CLUT_RING_BRIGHT),
                    _ => (2, CLUT_RING_DIM),
                };
                e.push(Op::Sprite {
                    x: gx - grow,
                    y: gy - grow,
                    src: SPRITE_RING[grow as usize - 1],
                    clut,
                    glass: true,
                });
            }
            e
        }
    }
}

/// What the pill that is partly recharged draws: `quadrants` of its four, filled clockwise.
pub fn pill_partial(origin: (i32, i32), pill: i32, quadrants: u8) -> PillExtras {
    let mut e = PillExtras::new(false);
    for i in 0..quadrants.min(4) as usize {
        quadrant(&mut e, origin, pill, i, (0, 0), CLUT_GEM_LIT, false);
    }
    e
}

/// What the ammunition does on screen, one step per HUD frame, from the energy the game reports
/// (0 to 100, ten to a pill): a spent pill breaks, a recharged one loads and echoes, and the pill
/// being recharged shows how far along it is. Each pill animates by itself, so rapid shots and
/// a recharge that gains several pills at once overlap cleanly.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct AmmoFx {
    energy: u16,
    slots: [PillFx; FX_SLOTS],
    /// Pills recharged by a jump of energy that have not started to load yet, and the frames to
    /// wait before the next one does.
    queue: (u8, u8),
    gap: u8,
}

/// Energy a pill holds.
pub const ENERGY_PER_PILL: u16 = 10;

impl AmmoFx {
    /// Starts at `energy` with nothing animating.
    pub const fn new(energy: u16) -> Self {
        Self {
            energy,
            slots: [PillFx::Idle; FX_SLOTS],
            queue: (0, 0),
            gap: 0,
        }
    }

    fn start(&mut self, fx: PillFx) {
        let pill = fx.pill();
        // An effect already on the pill is replaced by the new one.
        let slot = (0..FX_SLOTS)
            .find(|&i| self.slots[i].pill() == pill)
            .or_else(|| (0..FX_SLOTS).find(|&i| self.slots[i] == PillFx::Idle));
        if let Some(i) = slot {
            self.slots[i] = fx;
        }
    }

    /// Advance one HUD frame with the game's energy now `energy`.
    pub fn step(&mut self, energy: u16) {
        let energy = energy.min(COUNT as u16 * ENERGY_PER_PILL);
        for slot in self.slots.iter_mut() {
            match slot {
                PillFx::Idle => {}
                PillFx::Break { wait, .. } | PillFx::Load { wait, .. } if *wait > 0 => *wait -= 1,
                PillFx::Break { frame, .. } => {
                    *frame += 1;
                    if *frame >= BREAK_FRAMES {
                        *slot = PillFx::Idle;
                    }
                }
                PillFx::Load { frame, .. } => {
                    *frame += 1;
                    if *frame >= LOAD_FRAMES {
                        *slot = PillFx::Idle;
                    }
                }
            }
        }
        let (old, new) = (self.energy / ENERGY_PER_PILL, energy / ENERGY_PER_PILL);
        // The pills that were showing lit: those before the ones waiting to load.
        let lit = if self.queue.0 < self.queue.1 {
            u16::from(self.queue.0)
        } else {
            old
        };
        if new < old {
            self.queue.1 = self.queue.1.min(new as u8);
            self.queue.0 = self.queue.0.min(self.queue.1);
            // Pills are spent from the right: the last lit one breaks first.
            for (n, pill) in (new..lit).rev().enumerate() {
                self.start(PillFx::Break {
                    pill: pill as u8,
                    frame: 0,
                    wait: n as u8,
                });
            }
        } else if new > old {
            if new == old + 1 && energy - self.energy <= 2 && self.queue.0 == self.queue.1 {
                // A recharge that completes the pill it was filling has only the last quadrant
                // and the echo left.
                self.start(PillFx::Load {
                    pill: old as u8,
                    frame: 3,
                    wait: 0,
                });
            } else if self.queue.0 == self.queue.1 {
                self.queue = (old as u8, new as u8);
            } else {
                self.queue.1 = new as u8;
            }
        }
        self.energy = energy;
        // Pills recharged by a jump take their turns, a stagger apart.
        if self.gap > 0 {
            self.gap -= 1;
        } else if self.queue.0 < self.queue.1 && self.slots.contains(&PillFx::Idle) {
            self.start(PillFx::Load {
                pill: self.queue.0,
                frame: 0,
                wait: 0,
            });
            self.queue.0 += 1;
            self.gap = LOAD_STAGGER - 1;
        }
    }

    /// Whether any pill is still animating.
    pub fn busy(&self) -> bool {
        self.queue.0 < self.queue.1 || self.slots.iter().any(|&s| s != PillFx::Idle)
    }

    /// Write the pills into `state`: how many are lit, the effects, and how far the next pill is.
    pub fn apply(&self, state: &mut HudState) {
        state.energy = (self.energy / ENERGY_PER_PILL) as u8;
        state.fx = self.slots;
        state.partial = ((self.energy % ENERGY_PER_PILL) * 4 / ENERGY_PER_PILL) as u8;
        state.queued = self.queue;
    }
}

/// How a bar is folded away: it shortens from the right a cell at a time, then the stub that is left
/// slides left under the emblem. Everything is a whole pixel, and the shapes are the ones of the
/// full bar, moved, shortened or left out: nothing is scaled and no packet is rebuilt.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Fold {
    /// Cells still showing, counted from the left.
    pub cells: i32,
    /// Pixels the plate has lost on the right: the plate is that much narrower and the right end
    /// that much further left.
    pub shrink: i32,
    /// Pixels the whole bar has slid to the left.
    pub slide: i32,
}

impl Fold {
    /// A bar that is fully out.
    pub const FULL: Self = Self {
        cells: COUNT,
        shrink: 0,
        slide: 0,
    };
}

/// Cells and slide for each fold step, from 1 (nearly gone) to [`REVEAL_MAX`] (fully out).
const FOLD_STEPS: [(i32, i32); REVEAL_MAX as usize] = [
    (0, 22),
    (0, 8),
    (0, 0),
    (2, 0),
    (4, 0),
    (6, 0),
    (8, 0),
    (COUNT, 0),
];

/// Narrowest the plate gets: just enough that the two ends do not overlap.
const FOLD_MIN_PLATE: i32 = 2;

/// The fold of a bar of size `geo` at `reveal` (1 to [`REVEAL_MAX`]), or `None` when it is gone.
pub fn fold_of(reveal: u8, geo: &SizeGeo) -> Option<Fold> {
    if reveal == 0 {
        return None;
    }
    let (cells, slide) = FOLD_STEPS[(reveal.min(REVEAL_MAX) - 1) as usize];
    let shrink = if cells == 0 {
        geo.cap_x - geo.bar_x0 - FOLD_MIN_PLATE
    } else {
        (COUNT - cells) * geo.pitch
    };
    Some(Fold {
        cells,
        shrink,
        slide,
    })
}

/// Gems showing at `reveal` (of [`REVEAL_MAX`]): they pop out of the row from the right as the HUD
/// folds and pop in from the left as it unfolds.
pub fn gems_shown(reveal: u8) -> i32 {
    (i32::from(reveal.min(REVEAL_MAX)) * COUNT + i32::from(REVEAL_MAX) - 1) / i32::from(REVEAL_MAX)
}

/// The fold and unfold of the HUD, one step per HUD frame: the bar in front goes first, the bar
/// behind and each of the two follows [`FOLD_LAG`] frames later, the gems go with the bar in front,
/// and the emblem flashes for [`PULSE_FRAMES`] frames when the bars start to come out.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct HudAnim {
    reveal: [u8; 2],
    ammo: u8,
    lag: [u8; 2],
    open: bool,
    pulse: u8,
}

impl HudAnim {
    /// Fully unfolded.
    pub const fn open() -> Self {
        Self {
            reveal: [REVEAL_MAX; 2],
            ammo: REVEAL_MAX,
            lag: [0; 2],
            open: true,
            pulse: 0,
        }
    }

    /// Fully folded: only the emblem.
    pub const fn closed() -> Self {
        Self {
            reveal: [0; 2],
            ammo: 0,
            lag: [0; 2],
            open: false,
            pulse: 0,
        }
    }

    /// Advance one HUD frame towards open or closed. `front` is the active stance, whose bar goes
    /// first.
    pub fn step(&mut self, open: bool, front: Stance) {
        self.pulse = self.pulse.saturating_sub(1);
        if open != self.open {
            self.open = open;
            self.lag = [0; 2];
            self.lag[front.other().index()] = FOLD_LAG;
            self.pulse = if open { PULSE_FRAMES } else { 0 };
        }
        for (r, lag) in self.reveal.iter_mut().zip(self.lag.iter_mut()) {
            if *lag > 0 {
                *lag -= 1;
            } else if open {
                *r = (*r + 1).min(REVEAL_MAX);
            } else {
                *r = r.saturating_sub(1);
            }
        }
        self.ammo = if open {
            (self.ammo + 1).min(REVEAL_MAX)
        } else {
            self.ammo.saturating_sub(1)
        };
    }

    /// Whether any part of the HUD is still moving.
    pub fn moving(&self) -> bool {
        let target = if self.open { REVEAL_MAX } else { 0 };
        self.reveal.iter().any(|&r| r != target) || self.ammo != target || self.pulse > 0
    }

    /// Write the animation into `state`.
    pub fn apply(&self, state: &mut HudState) {
        state.reveal = self.reveal;
        state.ammo_reveal = self.ammo;
        state.pulse = self.pulse > 0;
    }
}

/// What makes the HUD unfold this tick.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct FoldTriggers {
    /// A hostile is inside the radius (with its hysteresis, see [`FoldPolicy::near`]).
    pub hostile_near: bool,
    /// Lock-on or targeting is active.
    pub targeting: bool,
    /// The player took damage this tick.
    pub damaged: bool,
    /// Health or ammunition changed this tick, in combat or not.
    pub changed: bool,
    /// The player is attached to an arch, recharging.
    pub attached: bool,
}

/// Ticks (of 60 a second) the HUD stays out after the last trigger.
pub const FOLD_GRACE_TICKS: u16 = 120;

/// Ticks the HUD stays out after only a change of health or ammunition, so it is seen.
pub const FOLD_CHANGE_TICKS: u16 = 90;

/// When the HUD is out: a trigger opens it and a grace period of ticks keeps it open.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct FoldPolicy {
    open: bool,
    grace: u16,
    near: bool,
}

impl FoldPolicy {
    /// Out, as at the start of a level.
    pub const fn new() -> Self {
        Self {
            open: true,
            grace: FOLD_GRACE_TICKS,
            near: false,
        }
    }

    /// Whether a hostile at squared distance `dist2` counts as near: inside the `enter` radius, or
    /// inside the larger `leave` radius if it already counted (the margin keeps the HUD from
    /// flickering at the edge of the radius).
    pub fn near(&mut self, dist2: Option<i32>, enter: i32, leave: i32) -> bool {
        let limit = if self.near { leave } else { enter };
        self.near = dist2.is_some_and(|d| d <= limit.saturating_mul(limit));
        self.near
    }

    /// Advance one tick and say whether the HUD should be out.
    pub fn step(&mut self, t: FoldTriggers) -> bool {
        if t.hostile_near || t.targeting || t.damaged || t.attached {
            self.grace = FOLD_GRACE_TICKS;
        } else if t.changed {
            self.grace = self.grace.max(FOLD_CHANGE_TICKS);
        } else {
            self.grace = self.grace.saturating_sub(1);
        }
        self.open = self.grace > 0;
        self.open
    }
}

impl Default for FoldPolicy {
    fn default() -> Self {
        Self::new()
    }
}

/// Which parts of a bar to paint.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Part {
    /// The translucent well and both ends, which carry translucent pixels.
    Glass,
    /// The opaque bands.
    Opaque,
    /// The well, the ends and the opaque bands: the plate without the cells.
    Plate,
    /// The cells.
    Cells,
}

/// The palette of a cell of the bar of `stance` at `size`, lit or empty. A cell packet only ever
/// changes between these two, so a health change is a one-word patch of the packet.
pub fn cell_clut(stance: Stance, size: usize, lit: bool) -> usize {
    stance.index() * CLUTS_PER_STANCE
        + size * CLUT_SIZE_STRIDE
        + if lit { CLUT_CELL_LIT } else { CLUT_CELL_EMPTY }
}

/// The palette of an ammunition gem, lit or empty.
pub fn gem_clut(lit: bool) -> usize {
    if lit {
        CLUT_GEM_LIT
    } else {
        CLUT_GEM_EMPTY
    }
}

/// Paint one complete bar of `stance`, `lit` cells lit, at `pose`, folded as `fold` says.
#[allow(clippy::too_many_arguments)]
pub fn bar(
    origin: (i32, i32),
    stance: Stance,
    pose: Pose,
    lit: u8,
    fold: Fold,
    part: Part,
    draw: &mut impl FnMut(Op),
) {
    let (left, top) = (origin.0 + pose.x - fold.slide, origin.1 + pose.y);
    let cap_x = GEO[pose.size].cap_x - fold.shrink;
    let s = stance.index();
    let geo = &GEO[pose.size];
    for band in &BANDS[s][pose.size][..geo.band_count] {
        let wanted = match part {
            Part::Plate => true,
            Part::Glass => band.glass,
            Part::Opaque => !band.glass,
            Part::Cells => false,
        };
        if wanted {
            draw(Op::Rect {
                x: left + geo.bar_x0,
                y: top + band.y0 as i32,
                w: cap_x - geo.bar_x0,
                h: (band.y1 - band.y0) as i32,
                rgb: band.rgb,
                glass: band.glass,
            });
        }
    }
    let base = s * CLUTS_PER_STANCE + pose.size * CLUT_SIZE_STRIDE;
    if part == Part::Glass || part == Part::Plate {
        for (x, src) in [(LCAP_X, geo.lcap), (cap_x, geo.cap)] {
            draw(Op::Sprite {
                x: left + x,
                y: top,
                src,
                clut: base + CLUT_CAP,
                glass: true,
            });
        }
    }
    if part == Part::Cells {
        for k in 0..fold.cells {
            draw(Op::Sprite {
                x: left + geo.cell_x0 + geo.pitch * k,
                y: top + geo.cell_row,
                src: geo.cell,
                clut: cell_clut(stance, pose.size, (k as u8) < lit),
                glass: false,
            });
        }
    }
}

/// The geometry of a bar at a depth between two sizes of the art, in 1/256 pixels: every number is
/// the two sizes' numbers mixed. Columns are those of [`SizeGeo`] (the left end starts at `LCAP_X`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Plane {
    /// The size of the art whose texels and palettes are used: the nearest.
    pub art: usize,
    pub pitch: i32,
    pub cell_x0: i32,
    pub cell_row: i32,
    pub cell_w: i32,
    pub cell_h: i32,
    pub bar_h: i32,
    pub bar_x0: i32,
    pub cap_x: i32,
    pub cap_w: i32,
    pub lcap_w: i32,
}

/// The plane at `depth` (see [`Xf::depth`]).
#[inline(never)]
pub fn plane(depth: i32) -> Plane {
    let depth = depth.clamp(0, (BACK_SIZE as i32) << 8);
    let lo = (depth >> 8) as usize;
    let hi = (lo + 1).min(BACK_SIZE);
    let f = depth & 255;
    let (a, b) = (&GEO[lo], &GEO[hi]);
    let mix = |x: i32, y: i32| x * (256 - f) + y * f;
    Plane {
        art: ((depth + 128) >> 8) as usize,
        pitch: mix(a.pitch, b.pitch),
        cell_x0: mix(a.cell_x0, b.cell_x0),
        cell_row: mix(a.cell_row, b.cell_row),
        cell_w: mix(a.cell.w as i32, b.cell.w as i32),
        cell_h: mix(a.cell.h as i32, b.cell.h as i32),
        bar_h: mix(a.bar_h, b.bar_h),
        bar_x0: mix(a.bar_x0, b.bar_x0),
        cap_x: mix(a.cap_x, b.cap_x),
        cap_w: mix(a.cap.w as i32, b.cap.w as i32),
        lcap_w: mix(a.lcap.w as i32, b.lcap.w as i32),
    }
}

/// The fold of a bar at `reveal` (1 to [`REVEAL_MAX`]) in `plane`, or `None` when it is gone.
fn fold_in(reveal: u8, plane: &Plane) -> Option<Fold> {
    if reveal == 0 {
        return None;
    }
    let (cells, slide) = FOLD_STEPS[(reveal.min(REVEAL_MAX) - 1) as usize];
    let shrink = if cells == 0 {
        ((plane.cap_x - plane.bar_x0) >> 8) - FOLD_MIN_PLATE
    } else {
        ((COUNT - cells) * plane.pitch) >> 8
    };
    Some(Fold {
        cells,
        shrink,
        slide,
    })
}

/// The fold of a bar placed at `at` when it is unfolded to `reveal`, or `None` when it is gone.
pub fn fold_at(reveal: u8, at: &Placement) -> Option<Fold> {
    match at {
        Placement::Rest(pose) => fold_of(reveal, &GEO[pose.size]),
        Placement::Moving(xf) => fold_in(reveal, &plane(xf.depth)),
    }
}

/// The four corners (top-left, top-right, bottom-left, bottom-right) of the rectangle `x0..x1` by
/// `y0..y1` of the bar's plane, given from the bar's top-left corner in 1/256 pixels, on the screen
/// in whole pixels. `anchor` is the corner's place on the screen, `half` the middle of the bar the
/// plane turns about.
///
/// The turn is about the vertical axis through the middle of the bar. A point `a` from the axis is
/// `a * cos` to the side and `a * sin` deeper, and the perspective that scales it by `F / (F + z)`
/// is taken to second order, so there is no division: `1 / (1 + e)` is `1 - e + e * e` for the small
/// `e = z / F` the swap reaches (the focal length `F` is 256 pixels). The scale depends on the
/// column alone, so a column's two corners share it, and the edges of neighbouring pieces meet
/// exactly. Not inlined: it is called for every piece and is the bulk of the code.
#[inline(never)]
fn corners(
    anchor: (i32, i32),
    half: (i32, i32),
    xf: &Xf,
    x0: i32,
    y0: i32,
    x1: i32,
    y1: i32,
) -> [(i16, i16); 4] {
    let column = |x: i32| {
        let a = x - (LCAP_X << 8) - half.0;
        let e = (a * xf.sin) >> 16;
        let s = 4096 - e + ((e * e) >> 12);
        let px = (anchor.0 + half.0 + ((((a * xf.cos) >> 12) * s) >> 12) + 128) >> 8;
        (px, s)
    };
    let (left, sl) = column(x0);
    let (right, sr) = column(x1);
    let (top, bottom) = (y0 - half.1, y1 - half.1);
    let py = |b: i32, s: i32| (anchor.1 + half.1 + ((b * s) >> 12) + 128) >> 8;
    let at = |x: i32, y: i32| (x as i16, y as i16);
    [
        at(left, py(top, sl)),
        at(right, py(top, sr)),
        at(left, py(bottom, sl)),
        at(right, py(bottom, sr)),
    ]
}

/// Where a bar on the move is on the screen, and the middle of it the plane turns about, both in
/// 1/256 pixels. The middle is the one of the whole bar, folded or not.
fn frame_of(origin: (i32, i32), xf: &Xf, pl: &Plane, fold: &Fold) -> ((i32, i32), (i32, i32)) {
    (
        (
            (origin.0 << 8) + xf.x - (fold.slide << 8),
            (origin.1 << 8) + xf.y,
        ),
        ((pl.cap_x + pl.cap_w - (LCAP_X << 8)) >> 1, pl.bar_h >> 1),
    )
}

/// The pixels a bar covers, folded as `fold` says: left, top, right, bottom.
pub fn bar_bounds(origin: (i32, i32), at: &Placement, fold: &Fold) -> [i32; 4] {
    match at {
        Placement::Rest(pose) => {
            let geo = &GEO[pose.size];
            let left = origin.0 + pose.x - fold.slide;
            let top = origin.1 + pose.y;
            [
                left + LCAP_X,
                top,
                left + geo.cap_x - fold.shrink + geo.cap.w as i32,
                top + geo.bar_h,
            ]
        }
        Placement::Moving(xf) => {
            let pl = plane(xf.depth);
            let (anchor, half) = frame_of(origin, xf, &pl, fold);
            let right = pl.cap_x - (fold.shrink << 8) + pl.cap_w;
            let p = corners(anchor, half, xf, LCAP_X << 8, 0, right, pl.bar_h);
            let (mut b, mut c) = ([i32::MAX; 2], [i32::MIN; 2]);
            for (x, y) in p {
                (b[0], b[1]) = (b[0].min(i32::from(x)), b[1].min(i32::from(y)));
                (c[0], c[1]) = (c[0].max(i32::from(x)), c[1].max(i32::from(y)));
            }
            [b[0], b[1], c[0] + 1, c[1] + 1]
        }
    }
}

/// A quad of a bar at rest as the rectangle or sprite it is: not turned, whole pixels, 1:1.
fn as_rest(op: Op) -> Op {
    match op {
        Op::Quad { p, rgb, glass } => Op::Rect {
            x: i32::from(p[0].0),
            y: i32::from(p[0].1),
            w: i32::from(p[1].0 - p[0].0),
            h: i32::from(p[2].1 - p[0].1),
            rgb,
            glass,
        },
        Op::TexQuad {
            p,
            src,
            clut,
            glass,
        } => Op::Sprite {
            x: i32::from(p[0].0),
            y: i32::from(p[0].1),
            src,
            clut,
            glass,
        },
        other => other,
    }
}

/// Paint one complete bar of `stance` on the move, `lit` cells lit, folded as `fold` says: the same
/// pieces as [`bar`], in the same order, each as a quad placed by [`corners`].
#[allow(clippy::too_many_arguments)]
#[inline(never)]
pub fn bar_moving(
    origin: (i32, i32),
    stance: Stance,
    xf: Xf,
    lit: u8,
    fold: Fold,
    part: Part,
    rest: bool,
    draw: &mut dyn FnMut(Op),
) {
    let mut put = |op: Op| draw(if rest { as_rest(op) } else { op });
    let pl = plane(xf.depth);
    let geo = &GEO[pl.art];
    let s = stance.index();
    let (anchor, half) = frame_of(origin, &xf, &pl, &fold);
    let at = |x0: i32, y0: i32, x1: i32, y1: i32| corners(anchor, half, &xf, x0, y0, x1, y1);
    let cap_x = pl.cap_x - (fold.shrink << 8);
    // The rows of the art's bands stretched over the rows of this depth.
    let stretch = pl.bar_h / geo.bar_h;
    for band in &BANDS[s][pl.art][..geo.band_count] {
        let wanted = match part {
            Part::Plate => true,
            Part::Glass => band.glass,
            Part::Opaque => !band.glass,
            Part::Cells => false,
        };
        if wanted {
            put(Op::Quad {
                p: at(
                    pl.bar_x0,
                    band.y0 as i32 * stretch,
                    cap_x,
                    band.y1 as i32 * stretch,
                ),
                rgb: band.rgb,
                glass: band.glass,
            });
        }
    }
    let base = s * CLUTS_PER_STANCE + pl.art * CLUT_SIZE_STRIDE;
    if part == Part::Glass || part == Part::Plate {
        for (x, w, src) in [
            (LCAP_X << 8, pl.lcap_w, geo.lcap),
            (cap_x, pl.cap_w, geo.cap),
        ] {
            put(Op::TexQuad {
                p: at(x, 0, x + w, pl.bar_h),
                src,
                clut: base + CLUT_CAP,
                glass: true,
            });
        }
    }
    if part == Part::Cells {
        for k in 0..fold.cells {
            let x = pl.cell_x0 + pl.pitch * k;
            put(Op::TexQuad {
                p: at(x, pl.cell_row, x + pl.cell_w, pl.cell_row + pl.cell_h),
                src: geo.cell,
                clut: cell_clut(stance, pl.art, (k as u8) < lit),
                glass: false,
            });
        }
    }
}

/// Paint one complete bar wherever it is, at rest or on the move.
#[allow(clippy::too_many_arguments)]
pub fn bar_at(
    origin: (i32, i32),
    stance: Stance,
    at: &Placement,
    lit: u8,
    fold: Fold,
    part: Part,
    draw: &mut dyn FnMut(Op),
) {
    match at {
        // At rest the bar is the plane at one of the art's sizes with no turn, drawn as the
        // rectangles and sprites the art was made for: the same pieces, so the same pixels.
        Placement::Rest(pose) => {
            bar_moving(origin, stance, plane_of(*pose), lit, fold, part, true, draw)
        }
        Placement::Moving(xf) => bar_moving(origin, stance, *xf, lit, fold, part, false, draw),
    }
}

/// The ops that set the mask a given way.
pub const MASK_SET: Op = Op::Mask {
    set: true,
    check: false,
};
/// Set and check, for the cells of the bar behind.
pub const MASK_SET_CHECK: Op = Op::Mask {
    set: true,
    check: true,
};
/// Check only, for the plate of the bar behind.
pub const MASK_CHECK: Op = Op::Mask {
    set: false,
    check: true,
};
/// Neither: the opaque parts of the front bar.
pub const MASK_OFF: Op = Op::Mask {
    set: false,
    check: false,
};

/// The clut of the emblem for `look`.
pub fn emblem_clut(look: EmblemLook) -> usize {
    match look {
        EmblemLook::Of(s) => s.index() * CLUTS_PER_STANCE + CLUT_EMBLEM,
        EmblemLook::Halfway => CLUT_EMBLEM_HALFWAY,
        EmblemLook::Pulse(s) => CLUT_EMBLEM_PULSE + s.index(),
    }
}

/// The emblem as one op, with its top-left at `origin`.
pub fn emblem_op(origin: (i32, i32), look: EmblemLook) -> Op {
    Op::Sprite {
        x: origin.0 + EMBLEM_X,
        y: origin.1 + EMBLEM_Y,
        src: SPRITE_EMBLEM,
        clut: emblem_clut(look),
        glass: false,
    }
}

/// Gem `k` as one op, lit or not, with the HUD's top-left at `origin`.
pub fn gem_op(origin: (i32, i32), k: i32, lit: bool) -> Op {
    Op::Sprite {
        x: origin.0 + GEM_X0 + GEM_PITCH * k,
        y: origin.1 + GEM_Y,
        src: SPRITE_GEM,
        clut: gem_clut(lit),
        glass: false,
    }
}

/// One complete bar on its own, at `origin`, at `size`: the same object the HUD composes, for
/// previews and tests.
pub fn bar_alone(
    origin: (i32, i32),
    stance: Stance,
    size: usize,
    lit: u8,
    draw: &mut impl FnMut(Op),
) {
    let pose = Pose { x: 0, y: 0, size };
    bar(origin, stance, pose, lit, Fold::FULL, Part::Plate, draw);
    bar(origin, stance, pose, lit, Fold::FULL, Part::Cells, draw);
}

/// Paint the HUD with its top-left at `origin`.
///
/// Painter's order, with a wrinkle. The wells are translucent, and the bar in front must hide the bar
/// behind it without letting it show through its well. So the translucent parts of the front bar
/// are painted first and mark the pixels they touch, the bar behind is painted next and skips
/// marked pixels, and the opaque parts of the front bar go on top. Any overlap of the two bars, at
/// any position, comes out the same way.
///
/// A translucent texel marks the pixel it lands on whether or not a mask was asked for (the GPU
/// keeps the texel's own bit 15). So the cells of the bar behind, which sit over its translucent
/// ends, are painted first, marking their pixels, and the plate of that bar follows and skips them.
pub fn compose(origin: (i32, i32), state: &HudState, draw: &mut impl FnMut(Op)) {
    let sc = scene(state);
    let lit = |s: Stance| state.health[s.index()];
    let fold_of_bar =
        |(stance, at): (Stance, Placement)| fold_at(state.reveal[stance.index()], &at);
    let (front_fold, behind_fold) = (fold_of_bar(sc.front), fold_of_bar(sc.behind));
    draw(MASK_SET);
    if let Some(fold) = front_fold {
        bar_at(
            origin,
            sc.front.0,
            &sc.front.1,
            lit(sc.front.0),
            fold,
            Part::Glass,
            &mut |op| draw(op),
        );
    }
    draw(MASK_SET_CHECK);
    if let Some(fold) = behind_fold {
        bar_at(
            origin,
            sc.behind.0,
            &sc.behind.1,
            lit(sc.behind.0),
            fold,
            Part::Cells,
            &mut |op| draw(op),
        );
    }
    draw(MASK_CHECK);
    if let Some(fold) = behind_fold {
        bar_at(
            origin,
            sc.behind.0,
            &sc.behind.1,
            lit(sc.behind.0),
            fold,
            Part::Plate,
            &mut |op| draw(op),
        );
    }
    draw(MASK_OFF);
    if let Some(fold) = front_fold {
        bar_at(
            origin,
            sc.front.0,
            &sc.front.1,
            lit(sc.front.0),
            fold,
            Part::Opaque,
            &mut |op| draw(op),
        );
        bar_at(
            origin,
            sc.front.0,
            &sc.front.1,
            lit(sc.front.0),
            fold,
            Part::Cells,
            &mut |op| draw(op),
        );
    }
    draw(emblem_op(origin, sc.emblem));
    let shown = if state.ammo_hint {
        COUNT
    } else {
        gems_shown(state.ammo_reveal)
    };
    for k in 0..shown {
        let extras = pill_state(origin, state, k);
        draw(gem_op(origin, k, extras.lit));
        for op in &extras.ops[..extras.n] {
            draw(*op);
        }
    }
}

/// How pill `k` looks in `state`: lit or empty underneath, and what is drawn over it by the effect it
/// is in, or the quadrants of the recharge it is half way through.
pub fn pill_state(origin: (i32, i32), state: &HudState, k: i32) -> PillExtras {
    if let Some(fx) = state.fx.iter().find(|f| f.pill() == Some(k as u8)) {
        return pill_fx(origin, k, *fx);
    }
    if i32::from(state.queued.0) <= k && k < i32::from(state.queued.1) {
        return pill_partial(origin, k, 0);
    }
    if k == i32::from(state.energy) && state.partial > 0 {
        return pill_partial(origin, k, state.partial);
    }
    let mut plain = pill_partial(origin, k, 0);
    plain.lit = k < i32::from(state.energy);
    plain
}

/// Names of the animation demos of [`demo_state`].
pub const DEMO_FOLD: u8 = 0;
pub const DEMO_SHOT: u8 = 1;
pub const DEMO_LOAD: u8 = 2;
pub const DEMO_RELOAD: u8 = 3;
pub const DEMO_JUMP: u8 = 4;

/// The HUD at frame `n` of an animation demo: `DEMO_FOLD` folds for 12 frames and then unfolds
/// for 12, `DEMO_SHOT` fires two shots, `DEMO_LOAD` recharges a pill a unit of energy at a time,
/// `DEMO_RELOAD` refills all ten pills at once and `DEMO_JUMP` gains three. Horizon in front,
/// health 7 and 5. The host viewer and the emulator check draw the same frames.
pub fn demo_state(demo: u8, n: u16) -> HudState {
    let mut state = HudState::rest(Stance::Horizon, [7, 5], 8);
    if demo == DEMO_FOLD {
        let mut anim = HudAnim::open();
        for i in 0..=n {
            anim.step(i >= 12, Stance::Horizon);
        }
        anim.apply(&mut state);
        return state;
    }
    let start = match demo {
        DEMO_SHOT => 100,
        DEMO_LOAD => 70,
        DEMO_RELOAD => 0,
        _ => 40,
    };
    let mut fx = AmmoFx::new(start);
    for i in 0..=n {
        let energy = match demo {
            DEMO_SHOT => match i {
                0 => 100,
                1..=8 => 80,
                _ => 60,
            },
            DEMO_LOAD => 70 + i * 2 / 3,
            DEMO_RELOAD => {
                if i == 0 {
                    0
                } else {
                    100
                }
            }
            _ => {
                if i == 0 {
                    40
                } else {
                    70
                }
            }
        };
        fx.step(energy);
    }
    fx.apply(&mut state);
    state
}
